/* ============================================================
 * card_events_probe / main script
 * 覆盖：裸全局 eventOn / eventEmit 往返 / eventOnce / 重复注册 no-op /
 *       stop() 取消 / 任意字符串事件名 / iframe 身份 / parent 可达 /
 *       ready+500ms 二次断言（force 重装 / 后注入回归）。
 * 每条断言：[CARD] card_events_probe <check> PASS|FAIL <detail>
 * 通道：console.log + window.parent.__rikkaLog(level, line)
 * ============================================================ */
(function () {
  'use strict';
  var TAG = 'card_events_probe';
  var EXPECTED_NAME = 'events_probe_main';
  var EXPECTED_ID = '577383d6-5b2f-4591-a4e8-ce07486a259e';
  var EXPECTED_IFRAME = 'TH-script--events_probe_main--577383d6-5b2f-4591-a4e8-ce07486a259e';
  var counts = { pass: 0, fail: 0 };

  function safe(v) {
    try { return (typeof v === 'string') ? v : JSON.stringify(v); }
    catch (e) { return String(v); }
  }
  function report(name, status, detail) {
    if (status === 'PASS') { counts.pass++; } else { counts.fail++; }
    var line = '[CARD] ' + TAG + ' ' + name + ' ' + status + ' ' + String(detail == null ? '' : detail);
    try { console.log(line); } catch (e) {}
    try {
      var p = window.parent;
      if (p && typeof p.__rikkaLog === 'function') { p.__rikkaLog(status === 'FAIL' ? 'error' : 'info', line); }
    } catch (e) {}
  }
  function check(name, fn) {
    try {
      var r = fn();
      if (r && r.ok === true) { report(name, 'PASS', r.detail); }
      else { report(name, 'FAIL', (r && r.detail) ? r.detail : 'assertion returned false'); }
    } catch (err) {
      report(name, 'FAIL', String((err && err.message) || err));
    }
  }

  /* ---- 0) parent.__rikkaLog 可达性（独立于事件系统） ---- */
  check('parent_rikka_log_reachable', function () {
    var p = window.parent;
    var has = !!(p && typeof p.__rikkaLog === 'function');
    return { ok: has, detail: 'window.parent=' + (p ? 'present' : 'MISSING') + ' typeof parent.__rikkaLog=' + (p ? (typeof p.__rikkaLog) : 'n/a') };
  });

  /* ---- 1) 裸全局事件 API 存在性 ---- */
  var helperNames = ['eventOn','eventOnce','eventEmit','eventEmitAndWait','eventRemoveListener','eventMakeLast','eventMakeFirst','eventClearEvent','eventClearListener','eventClearAll'];
  var missing = [];
  for (var hi = 0; hi < helperNames.length; hi++) {
    if (typeof window[helperNames[hi]] !== 'function') { missing.push(helperNames[hi]); }
  }
  var hasEventOn = (typeof eventOn === 'function');
  check('eventOn_exists', function () {
    return { ok: hasEventOn, detail: 'typeof eventOn=' + (typeof eventOn) };
  });
  check('event_helpers_exist', function () {
    return { ok: missing.length === 0, detail: 'missing=' + JSON.stringify(missing) };
  });

  /* ---- 2) 脚本身份（不依赖事件系统） ---- */
  check('identity_script_name', function () {
    if (typeof getScriptName !== 'function') { return { ok: false, detail: 'getScriptName not a function' }; }
    var v = getScriptName();
    return { ok: v === EXPECTED_NAME, detail: 'getScriptName()=' + safe(v) + ' expected=' + EXPECTED_NAME };
  });
  check('identity_script_id', function () {
    if (typeof getScriptId !== 'function') { return { ok: false, detail: 'getScriptId not a function' }; }
    var v = getScriptId();
    return { ok: v === EXPECTED_ID, detail: 'getScriptId()=' + safe(v) + ' expected=' + EXPECTED_ID };
  });
  check('identity_iframe_name', function () {
    if (typeof getIframeName !== 'function') { return { ok: false, detail: 'getIframeName not a function' }; }
    var v = getIframeName();
    var n = window.name;
    return { ok: v === EXPECTED_IFRAME && n === EXPECTED_IFRAME, detail: 'getIframeName()=' + safe(v) + ' window.name=' + safe(n) + ' expected=' + EXPECTED_IFRAME };
  });
  check('identity_tavern_helper_mirror', function () {
    if (!window.TavernHelper || typeof window.TavernHelper.getScriptName !== 'function') { return { ok: false, detail: 'TavernHelper.getScriptName missing' }; }
    var a = getScriptName();
    var b = window.TavernHelper.getScriptName();
    return { ok: a === EXPECTED_NAME && b === EXPECTED_NAME, detail: 'bare=' + safe(a) + ' helper=' + safe(b) };
  });

  /* ---- 3) 事件往返与语义（依赖 eventOn） ---- */
  if (!hasEventOn) {
    var dependent = ['event_emit_roundtrip','event_once_single_fire','event_duplicate_register_noop','event_stop_cancels','arbitrary_event_name_registrable','event_multi_listener_isolated','eventOn_alive_after_ready_500ms'];
    for (var di = 0; di < dependent.length; di++) {
      report(dependent[di], 'FAIL', 'skipped: eventOn missing (typeof=' + (typeof eventOn) + ')');
    }
  } else {
    check('event_emit_roundtrip', function () {
      var got = [];
      var sub = eventOn('card_probe.evt.roundtrip', function (v) { got.push(v); });
      eventEmit('card_probe.evt.roundtrip', 'hello-1');
      if (sub && typeof sub.stop === 'function') { sub.stop(); }
      return { ok: got.length === 1 && got[0] === 'hello-1', detail: 'got=' + safe(got) };
    });

    check('event_once_single_fire', function () {
      var n = 0;
      eventOnce('card_probe.evt.once', function () { n++; });
      eventEmit('card_probe.evt.once', 'a');
      eventEmit('card_probe.evt.once', 'b');
      return { ok: n === 1, detail: 'count=' + n + ' (expected 1)' };
    });

    check('event_duplicate_register_noop', function () {
      var n = 0;
      var listener = function () { n++; };
      eventOn('card_probe.evt.dup', listener);
      eventOn('card_probe.evt.dup', listener);
      eventEmit('card_probe.evt.dup', 'x');
      eventRemoveListener('card_probe.evt.dup', listener);
      return { ok: n === 1, detail: 'count=' + n + ' (expected 1)' };
    });

    check('event_stop_cancels', function () {
      var n = 0;
      var listener = function () { n++; };
      var sub = eventOn('card_probe.evt.stop', listener);
      var hasStop = !!(sub && typeof sub.stop === 'function');
      eventEmit('card_probe.evt.stop', 'before');
      if (hasStop) { sub.stop(); }
      eventEmit('card_probe.evt.stop', 'after');
      return { ok: hasStop && n === 1, detail: 'hasStop=' + hasStop + ' count=' + n + ' (expected 1)' };
    });

    check('arbitrary_event_name_registrable', function () {
      var got = [];
      eventOn('mag_variable_update_ended', function () { got.push('mvu'); });
      eventOn('card probe weird.name/with space', function () { got.push('weird'); });
      eventEmit('mag_variable_update_ended', { ok: true });
      eventEmit('card probe weird.name/with space');
      return { ok: got.length === 2, detail: 'got=' + safe(got) };
    });

    check('event_multi_listener_isolated', function () {
      var a = 0, b = 0;
      eventOn('card_probe.evt.multi', function () { a++; });
      eventOn('card_probe.evt.multi', function () { b++; });
      eventEmit('card_probe.evt.multi');
      return { ok: a === 1 && b === 1, detail: 'a=' + a + ' b=' + b };
    });
  }

  /* ---- 4) ready + 500ms 二次断言（force 重装 / 后注入路径） ---- */
  function aliveCheck() {
    check('eventOn_alive_after_ready_500ms', function () {
      return { ok: typeof eventOn === 'function', detail: 'typeof eventOn=' + (typeof eventOn) + ' at ready+500ms' };
    });
    setTimeout(function () {
      var p = counts.pass, f = counts.fail;
      report('summary', f === 0 ? 'PASS' : 'FAIL', 'pass=' + p + ' fail=' + f);
      try { if (window.toastr && typeof toastr.info === 'function') { toastr.info('card_events_probe: pass=' + p + ' fail=' + f); } } catch (e) {}
    }, 50);
  }
  if (typeof $ === 'function') {
    check('jquery_available', function () { return { ok: true, detail: 'typeof $=' + (typeof $) }; });
    $(function () { setTimeout(aliveCheck, 500); });
  } else {
    check('jquery_available', function () { return { ok: false, detail: 'typeof $=' + (typeof $) }; });
    setTimeout(aliveCheck, 500);
  }
})();

/* card_events_probe / second iframe：per-iframe 身份 + 事件往返（跨 iframe 独立断言） */
(function () {
  'use strict';
  var TAG = 'card_events_probe';
  var EXPECTED_NAME = 'events_probe_identity_b';
  var EXPECTED_ID = '6d4a5b75-f7f0-4fd1-8035-560b5213aa1d';
  var EXPECTED_IFRAME = 'TH-script--events_probe_identity_b--6d4a5b75-f7f0-4fd1-8035-560b5213aa1d';
  function safe(v) { try { return (typeof v === 'string') ? v : JSON.stringify(v); } catch (e) { return String(v); } }
  function report(name, status, detail) {
    var line = '[CARD] ' + TAG + ' ' + name + ' ' + status + ' ' + String(detail == null ? '' : detail);
    try { console.log(line); } catch (e) {}
    try { var p = window.parent; if (p && typeof p.__rikkaLog === 'function') { p.__rikkaLog(status === 'FAIL' ? 'error' : 'info', line); } } catch (e) {}
  }
  function check(name, fn) {
    try {
      var r = fn();
      if (r && r.ok === true) { report(name, 'PASS', r.detail); }
      else { report(name, 'FAIL', (r && r.detail) ? r.detail : 'assertion returned false'); }
    } catch (err) { report(name, 'FAIL', String((err && err.message) || err)); }
  }
  check('b_parent_rikka_log_reachable', function () {
    var p = window.parent;
    return { ok: !!(p && typeof p.__rikkaLog === 'function'), detail: 'typeof parent.__rikkaLog=' + (p ? (typeof p.__rikkaLog) : 'n/a') };
  });
  check('b_eventOn_exists', function () { return { ok: typeof eventOn === 'function', detail: 'typeof eventOn=' + (typeof eventOn) }; });
  check('b_identity_script_name', function () {
    if (typeof getScriptName !== 'function') { return { ok: false, detail: 'getScriptName not a function' }; }
    var v = getScriptName();
    return { ok: v === EXPECTED_NAME, detail: 'getScriptName()=' + safe(v) + ' expected=' + EXPECTED_NAME };
  });
  check('b_identity_script_id', function () {
    if (typeof getScriptId !== 'function') { return { ok: false, detail: 'getScriptId not a function' }; }
    var v = getScriptId();
    return { ok: v === EXPECTED_ID, detail: 'getScriptId()=' + safe(v) + ' expected=' + EXPECTED_ID };
  });
  check('b_identity_iframe_name', function () {
    if (typeof getIframeName !== 'function') { return { ok: false, detail: 'getIframeName not a function' }; }
    var v = getIframeName();
    return { ok: v === EXPECTED_IFRAME && window.name === EXPECTED_IFRAME, detail: 'getIframeName()=' + safe(v) + ' window.name=' + safe(window.name) + ' expected=' + EXPECTED_IFRAME };
  });
  check('b_event_emit_roundtrip', function () {
    var n = 0;
    var sub = eventOn('card_probe_b.evt.roundtrip', function () { n++; });
    eventEmit('card_probe_b.evt.roundtrip', 'b');
    if (sub && typeof sub.stop === 'function') { sub.stop(); }
    return { ok: n === 1, detail: 'count=' + n + ' (expected 1)' };
  });
})();

/* card_events_probe / disabled canary —— enabled:false，正常情况下永不执行。
 * 若该行出现在日志里，说明宿主忽略了 enabled 标志。 */
(function () {
  'use strict';
  try {
    var line = '[CARD] card_events_probe disabled_canary_ran FAIL disabled script executed despite enabled=false';
    try { console.log(line); } catch (e) {}
    try { if (window.parent && typeof window.parent.__rikkaLog === 'function') { window.parent.__rikkaLog('error', line); } } catch (e) {}
  } catch (err) {
    try { console.log('[CARD] card_events_probe disabled_canary_ran FAIL ' + String((err && err.message) || err)); } catch (e) {}
  }
})();
